import { useState } from "react";
import { useEffect } from "react";
import { Button } from "@mui/material";
import video from "../Images/identify_confused_word.mp4";
import { useNavigate } from "react-router-dom";
import "../style/level1.css";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useTranslation } from "react-i18next";

const Selectlevel = () => {
  var [flag, setFlag] = useState(true);
  const { t, i18n } = useTranslation();

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level start page");

  const navigate = useNavigate();
  useEffect(() => {
    document
      .getElementById("myVideo")
      .addEventListener("loadedmetadata", function () {
        document.getElementById("myVideo").play();
      });
  }, []);

  const playVideo = () => {
    const videoElement = document.getElementById("myVideo");
    videoElement.play().catch((error) => {
      console.error("Error attempting to play:", error);
    });
  };

  const tolevel1 = () => {
    navigate("/launchpage/englishactivity/verbform/level1");

    ReactGA.event({
      action:
        'English Identify confused words | CDAC-OlabsNxtG-En-11 | Clicked on level 1 "Lets Go" button',
      category:
        'English CDAC-OlabsNxtG-En-11 | level 1 "Lets Go" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-11 | "Lets Go" button clicked and level 1 started',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level 1 "Lets Go" button',
      "Clicked",
      'Level 1 "Lets Go" button clicked and level 1 started'
    );
  };

  const end = () => {
    setFlag(false);
  };

  return (
    <div
      className="row d-flex justify-content-center align-items-center"
      style={{
        height: "100%",
        width: "100%",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        marginLeft: "auto",
        marginRight: "auto",
        overflow: "auto",
      }}
    >
      <div className="row d-flex justify-content-center align-items-center">
        <div className="row" style={{ height: "90%" }}>
          <video
            className="video"
            id="myVideo"
            width="50%"
            height="95%"
            autoplay
            muted
            onEnded={end}
          >
            <source src={video} type="video/mp4" />
          </video>
        </div>
        <div
          className="row-md-auto d-flex justify-content-center align-items-center"
          style={{ paddingTop: "5px" }}
        >
          <Button id="letgo" variant="contained" onClick={tolevel1} style={{fontSize: "calc(.6rem + .4vw)",backgroundColor: "#0F477E"}}>
            {t("lets_go")}
          </Button>
        </div>
      </div>
      {/* <InfoPopUpForDetailView
      openDialog={showDialogue}
      onAgree={onAgree}
      content={<ViewDetailsPopup sentence={sentence} />}
      popuptitle="Hint"
    /> */}
    </div>
  );
};

export default Selectlevel;
